package com.example.authUtils;

import io.jsonwebtoken.*;
import io.jsonwebtoken.security.Keys;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.crypto.SecretKey;
import java.util.Date;

/**
 * JWT Utility class for validating and extracting claims from JWT tokens.
 * 
 * NOTE: JWT tokens are generated by NestJS authentication service (once ready).
 * The generateToken() method is kept as temporary fallback during development.
 * This utility validates signatures and extracts claims.
 * 
 * The JWT token contains (set by NestJS):
 * - subject (username)
 * - clientId (custom claim)
 * - role (CLIENT, EMPLOYEE_ADMIN, or EMPLOYEE_REPORTER)
 * - issuedAt
 * - expiresAt
 */
@Component
public class JwtUtil {
    private static final Logger logger = LoggerFactory.getLogger(JwtUtil.class);
    
    @Value("${jwt.secret}")
    private String jwtSecret;
    
    @Value("${jwt.expiration}")
    private long jwtExpirationMs;
    
    /**
     * Generate a JWT token with clientId and role embedded in the claims
     * TEMPORARY: This method is kept for development/testing. Will be deleted when NestJS is ready.
     * 
     * @param username the username
     * @param clientId the client ID associated with the user
     * @param role the role (CLIENT, EMPLOYEE_ADMIN, EMPLOYEE_REPORTER)
     * @return the JWT token string
     */
    public String generateToken() {
        return "${JWT_TOKEN}";
    }

   
    
    /**
     * Validate JWT token signature and expiration
     * 
     * @param token the JWT token
     * @return true if token is valid, false otherwise
     */
    public boolean validateToken(String token) {
        try {
            SecretKey key = Keys.hmacShaKeyFor(jwtSecret.getBytes());
            Jwts.parserBuilder()
                    .setSigningKey(key)
                    .build()
                    .parseClaimsJws(token);
            logger.debug("JWT token validated successfully");
            return true;
        } catch (SecurityException e) {
            logger.error("Invalid JWT signature: {}", e.getMessage());
        } catch (MalformedJwtException e) {
            logger.error("Invalid JWT token: {}", e.getMessage());
        } catch (ExpiredJwtException e) {
            logger.error("Expired JWT token: {}", e.getMessage());
        } catch (UnsupportedJwtException e) {
            logger.error("Unsupported JWT token: {}", e.getMessage());
        } catch (IllegalArgumentException e) {
            logger.error("JWT claims string is empty: {}", e.getMessage());
        }
        return false;
    }
    
    /**
     * Extract username from JWT token
     * 
     * @param token the JWT token
     * @return the username (subject)
     */
    public String getUsernameFromToken(String token) {
        return getClaimsFromToken(token).getSubject();
    }
    
    /**
     * Extract clientId from JWT token
     * This is the key method for getting clientId from the token
     * 
     * @param token the JWT token
     * @return the clientId
     */
    public Long getClientIdFromToken(String token) {
        return getClaimsFromToken(token).get("clientId", Long.class);
    }

    /**
     * Extract role from JWT token
     * Role is set by NestJS during token generation
     * 
     * @param token the JWT token
     * @return the role (CLIENT, EMPLOYEE_ADMIN, or EMPLOYEE_REPORTER)
     */
    public String getRoleFromToken(String token) {
        return getClaimsFromToken(token).get("role", String.class);
    }
    
    /**
     * Extract all claims from JWT token
     * 
     * @param token the JWT token
     * @return the Claims object
     */
    private Claims getClaimsFromToken(String token) {
        SecretKey key = Keys.hmacShaKeyFor(jwtSecret.getBytes());
        return Jwts.parserBuilder()
                .setSigningKey(key)
                .build()
                .parseClaimsJws(token)
                .getBody();
    }
}